import json
from pathlib import Path
root=Path('artifacts/api-server/src/rag/sources')
base=json.loads(Path('docs/guideline-refresh/baseline-library.json').read_text())
evidence=[];changes=[]
def source(id,org,title,date,url,locator,claim,pop='See claim scope',strength=None):
 evidence.append(dict(id=id,organization=org,title=title,publicationDate=date,accessDate='2026-10-15',url=url,locator=locator,claim=claim,population=pop,recommendationStrength=strength,evidenceCertainty=None,access='Original official page read; limited paraphrase',rights='Limited attributed paraphrase; no blanket commercial-use clearance',supersessionCheck='Official source read on access date; comprehensive surveillance remains pending'))
def patch(i,old,new,ids,reason):
 assert old in base[i]['content'],(i,old)
 changes.append(dict(index=i,old=old,new=new,evidence=ids,reason=reason))
source('bp-2025','AHA/ACC','2025 High Blood Pressure Guideline: Top Things to Know','2025-08-14','https://professional.heart.org/en/science-news/2025-high-blood-pressure-guideline/top-things-to-know','Items 4, 6–8, 10','Use explicit systolic OR diastolic hypertension criteria; use PREVENT-CVD 7.5% risk for selected stage-1 treatment, and treat persistent lower-risk stage 1 after 3–6 months of lifestyle intervention. Stage 2 favors two first-line classes.','Adults; pregnancy and frailty require separate guidance')
patch(0,'Blood pressure classification per 2017 ACC/AHA guideline (updated 2023):\n- Normal: <120/<80 mmHg\n- Elevated: 120-129/<80 mmHg\n- Stage 1 Hypertension: 130-139/80-89 mmHg\n- Stage 2 Hypertension: ≥140/≥90 mmHg','Blood pressure categories (2025 AHA/ACC):\n- Normal: systolic <120 AND diastolic <80 mmHg\n- Elevated: systolic 120–129 AND diastolic <80 mmHg\n- Stage 1: systolic 130–139 OR diastolic 80–89 mmHg\n- Stage 2: systolic ≥140 OR diastolic ≥90 mmHg',['bp-2025'],'Correct category logic and unsupported 2023 update label')
patch(0,'- Stage 1 HTN + established CVD or 10-year ASCVD risk ≥10%: initiate pharmacotherapy alongside lifestyle\n- Stage 1 HTN + 10-year ASCVD risk <10%: lifestyle modification first, reassess in 3-6 months\n- Stage 2 HTN: antihypertensive pharmacotherapy + lifestyle modification','- Add medication for average BP ≥140/90, or ≥130/80 with CVD, prior stroke, diabetes, CKD, or PREVENT-CVD 10-year risk ≥7.5%.\n- Lower-risk stage 1: initiate medication if average BP remains ≥130/80 after 3–6 months of lifestyle treatment.\n- Stage 2: prefer two first-line classes, ideally a single-pill combination, alongside lifestyle treatment.',['bp-2025'],'Replace obsolete risk threshold and add escalation')
source('lipids-2026','AHA/ACC','2026 Dyslipidemia Guideline: Top Things to Know','2026-03-13','https://professional.heart.org/en/science-news/2026-guideline-on-the-management-of-dyslipidemia/top-things-to-know','Items 2–3, 8–9','PREVENT-ASCVD replaces PCE for applicable primary prevention; consider LLT at 3–<5%, and more strongly at 5–<10% after discussion. Very-high-risk ASCVD target LDL-C <55 mg/dL; other ASCVD generally <70.','Risk-based adult lipid management; not a universal drug ladder')
patch(6,'4. Primary prevention, no DM, age 40-75, LDL 70-189, 10-yr ASCVD risk ≥7.5%: moderate-high intensity statin','4. Applicable primary prevention: use PREVENT-ASCVD with patient-specific risk discussion; lipid-lowering therapy may be considered at 3–<5% and should be considered at 5–<10% 10-year risk.',['lipids-2026'],'Replace old pooled-cohort threshold')
patch(6,'10-year ASCVD risk calculator: ACC/AHA Pooled Cohort Equations (race/sex-specific)','Risk assessment update: use PREVENT-ASCVD in applicable adults aged 30–79. Very-high-risk ASCVD: LDL-C goal <55 mg/dL; other ASCVD generally <70 mg/dL. Treatment intensity and additions depend on risk and response, not one universal ladder.',['lipids-2026'],'Update calculator and risk-specific targets')
for i in [9,151]:
 old='LDL goal: <100 mg/dL; <70 mg/dL with established ASCVD' if i==9 else '- LDL target: <100 mg/dL (high-intensity statin if ASCVD risk >10%); <70 mg/dL for established ASCVD'
 patch(i,old,'Lipid goals: assess ASCVD risk separately; 2026 AHA/ACC recommends LDL-C <55 mg/dL in very-high-risk ASCVD and generally <70 mg/dL in other ASCVD. Do not use a universal LDL <100 target.',['lipids-2026'],'Correct obsolete blanket lipid goals without claiming full ADA 2026 review')
source('clozapine-rems','FDA','FDA removes clozapine REMS','2025-08-27','https://www.fda.gov/drugs/drug-safety-communications/fda-removes-risk-evaluation-and-mitigation-strategy-rems-program-antipsychotic-drug-clozapine','What Is FDA Announcing?','Clozapine REMS ended June 13, 2025; severe neutropenia risk and label-based ANC monitoring remain.','US clozapine use')
patch(18,'requires mandatory REMS monitoring (ANC weekly/biweekly) due to agranulocytosis risk','FDA removed the REMS effective June 13, 2025; continue ANC monitoring according to current prescribing information because severe neutropenia risk remains',['clozapine-rems'],'Remove obsolete REMS requirement without removing monitoring')
source('oxbryta-withdrawal','FDA','Oxbryta withdrawal safety alert','2024-09-26','https://www.fda.gov/drugs/drug-alerts-and-statements/fda-alerting-patients-and-health-care-professionals-about-voluntary-withdrawal-oxbryta-market-due','Safety alert paragraphs 1–3','Voxelotor was withdrawn for safety concerns; FDA advises clinicians to stop prescribing it.','Sickle cell disease')
patch(115,'VOXELOTOR (Oxbryta): increases HbO2 affinity; reduces hemolysis; FDA-approved for hemoglobin improvement','VOXELOTOR (Oxbryta): withdrawn from the market in September 2024 for safety concerns. FDA advises clinicians to stop prescribing it; it is not an available treatment option.',['oxbryta-withdrawal'],'Remove withdrawn therapy as an active option')
source('andexxa-sales','FDA','Update on the Safety of Andexxa','2025-12-22','https://www.fda.gov/safety/medical-product-safety-information/update-safety-andexxa-astrazeneca-fda-safety-communication','Issue paragraphs 1–3','FDA found risks outweighed benefits; AstraZeneca ended US manufacture and sales after December 22, 2025.','US market; do not extrapolate availability internationally')
patch(55,'- Apixaban/rivaroxaban: andexanet alfa (Andexxa — specific reversal); 4-factor PCC (off-label)','- Apixaban/rivaroxaban reversal: Andexxa is not an available US treatment option following the December 2025 FDA safety update and end of US sales. Select a current institutional reversal pathway; specific alternative dosing remains to be verified.',['andexxa-sales'],'Correct US availability; do not invent a replacement dose')
source('crc-grades','USPSTF','Colorectal Cancer Screening: Clinician Summary','2021-05-18','https://www.uspreventiveservicestaskforce.org/uspstf/document/ClinicalSummaryFinal/colorectal-cancer-screening','Recommendation summary','Average-risk asymptomatic adults: ages 50–75 Grade A; 45–49 Grade B; selected 76–85 Grade C.','Average-risk adults without symptoms')
patch(21,'Grade A (age 45-75) and Grade B (age 45-49)','Grade A (age 50–75), Grade B (age 45–49), and selective Grade C (age 76–85)',['crc-grades'],'Correct overlapping grade assignment')
source('pop-missed','CDC','US SPR: Progestin-Only Pills','2024-11-18','https://www.cdc.gov/contraception/hcp/usspr/progestin-only-pills.html','Missed POPs; Figure 5','Norethindrone/norgestrel pills are missed after >3 hours; take promptly and use backup for two days. Drospirenone has different late/missed-pill rules.','Hormonal POPs; not combined pills')
patch(104,'must take same time daily (±3 hours for older generation; ±24 hours for norethindrone 0.35mg)','norethindrone or norgestrel is missed if >3 hours late: take promptly and use backup until taken correctly for 2 days. Drospirenone uses a different protocol; do not apply its timing to norethindrone.',['pop-missed'],'Correct formulation-specific missed-pill window')
source('mac-prophylaxis','NIH','Disseminated Mycobacterium avium Complex: Adult and Adolescent OIs',None,'https://clinicalinfo.hiv.gov/en/guidelines/hiv-clinical-guidelines-adult-and-adolescent-opportunistic-infections/disseminated','Preventing Disease: Primary Prophylaxis','MAC prophylaxis: CD4 <50 plus no ART, persistent viremia, or no suppressive regimen; not needed when ART starts immediately. Exclude disseminated MAC before prophylaxis.','Adults/adolescents with HIV','AI for indications; AII for immediate-ART exception')
patch(31,'- <100 cells/mcL: also MAC prophylaxis (azithromycin 1200mg weekly or clarithromycin) [unless on effective ART with rising CD4]','- MAC prophylaxis: CD4 <50 cells/mcL AND not receiving ART, remaining viremic, or no fully suppressive regimen available. No primary prophylaxis when ART is initiated immediately. Rule out disseminated MAC first.',['mac-prophylaxis'],'Correct CD4 threshold and ART exception')
source('hiv-initial','NIH/DHHS','Initial Combination Antiretroviral Regimens','2026-09-24','https://clinicalinfo.hiv.gov/en/guidelines/hiv-clinical-guidelines-adult-and-adolescent-arv/what-start-initial-combination-regimens','Table 6a and Table 6b','For most without prior CAB-LA exposure: BIC/TAF/FTC or DTG plus TAF/TDF plus FTC/3TC. DTG/3TC requires known HBV status and resistance results and is not for rapid initiation. DTG/ABC/3TC is a different regimen.','Initial adult/adolescent ART; pregnancy has separate recommendations','AI for listed most-person regimens')
patch(111,'- Dolutegravir + TAF/FTC (Triumeq or combination): preferred for women of childbearing age (lower NTD risk than older InSTIs)','- DTG plus TAF or TDF plus FTC or 3TC is an initial option for most people without prior CAB-LA exposure. DTG/ABC/3TC is a different regimen; do not call DTG + TAF/FTC “Triumeq.” Pregnancy requires the separate perinatal guideline.',['hiv-initial'],'Correct drug-combination misidentification')
source('flu-dosing','CDC','Influenza Antiviral Medications: Summary for Clinicians',None,'https://www.cdc.gov/flu/hcp/antivirals/summary-clinicians.html','Tables 2–3; Hospitalized Patients','Adult oseltamivir treatment: CrCl 31–60: 30 mg PO twice daily; 11–30: 30 mg PO daily, for five days in uncomplicated influenza. Baloxavir adult dose boundary is ≥80 kg. Routine single-dose peramivir is not the hospitalized-patient default.','Adult treatment; dialysis/pediatric dosing require separate rows')
patch(126,'reduce to 75 mg/day if GFR <30','adult treatment adjustments use CrCl: 31–60 mL/min, 30 mg PO twice daily; 11–30 mL/min, 30 mg PO daily. Standard uncomplicated treatment duration is 5 days; dialysis requires its own regimen.',['flu-dosing'],'Correct unsafe renal dose and distinguish CrCl from eGFR')
patch(126,'40 mg single dose (≤80 kg) or 80 mg (>80 kg)','adult oral dose: 40 mg once at 20–<80 kg or 80 mg once at ≥80 kg',['flu-dosing'],'Correct 80 kg dose boundary')
patch(126,'- Peramivir 600 mg IV x 1 dose: hospitalized patients unable to tolerate oral','- Peramivir: single-dose treatment is an uncomplicated outpatient regimen with renal adjustment. It is not routinely recommended for hospitalized influenza; oral/enteric oseltamivir is preferred.',['flu-dosing'],'Remove unsupported inpatient substitution')
source('gas-treatment','CDC','Clinical Guidance for Group A Streptococcal Pharyngitis','2025-11-18','https://www.cdc.gov/group-a-strep/hcp/clinical-guidance/strep-throat.html','Testing; Recommended antibiotics','Treat confirmed GAS. Oral amoxicillin: 50 mg/kg once daily (max 1 g) or 25 mg/kg twice daily (max 500 mg/dose), ten days. Back up a negative RADT with culture in symptomatic children aged ≥3.','GAS pharyngitis; distinguish viral illness')
patch(125,'- ≥4: Empirical antibiotic treatment acceptable without testing','- High clinical scores guide testing; do not equate a score alone with confirmed GAS. Treat a positive RADT or throat culture.',['gas-treatment'],'Avoid score-only empiric antibiotics')
patch(125,'- First-line: Amoxicillin 500 mg BID or 250 mg TID x 10 days','- First-line oral amoxicillin: 50 mg/kg once daily (maximum 1000 mg) OR 25 mg/kg twice daily (maximum 500 mg per dose), for 10 days.',['gas-treatment'],'Replace non-CDC amoxicillin regimen with population-specific dose')
patch(125,'FULL 10-DAY COURSE required to prevent acute rheumatic fever (ARF).','Complete the selected regimen: penicillin/amoxicillin uses 10 days; azithromycin uses its separate 5-day regimen.',['gas-treatment'],'Resolve conflicting universal-duration instruction')
source('chlamydia-followup','CDC','STI Treatment Guidelines: Chlamydial Infections','2021-07-22','https://www.cdc.gov/std/treatment-guidelines/chlamydia.htm','Treatment; Follow-Up; Pregnancy','Doxycycline is preferred in nonpregnant adults; azithromycin remains an alternative with lower rectal efficacy. Test of cure is recommended in pregnancy and selected nonpregnant situations; distinguish it from three-month retesting.','Adult/adolescent chlamydia; pregnancy uses its own regimen')
patch(29,'- Azithromycin 1g single dose (alternative — acceptable for urogenital only)','- Azithromycin 1 g orally once is an alternative in nonpregnant adults when appropriate; lower rectal efficacy may require follow-up. Pregnancy uses a separate recommended regimen.',['chlamydia-followup'],'Remove unsupported site-only prohibition')
patch(29,'- Test-of-cure: only needed in pregnancy; retest all patients at 3 months','- Test of cure: recommended about 4 weeks after treatment in pregnancy; in nonpregnant patients, consider when adherence is uncertain, symptoms persist, or reinfection is suspected. Retest at about 3 months for reinfection.',['chlamydia-followup'],'Add nonpregnancy exceptions')
source('aom-diagnosis','CDC','Outpatient Clinical Care for Pediatric Populations',None,'https://www.cdc.gov/antibiotic-use/hcp/clinical-care/pediatric-outpatient.html','Acute Otitis Media','AOM requires effusion plus qualifying bulging/otorrhea or mild bulging with recent pain/intense erythema; these are alternatives. Amoxicillin is initial therapy when eligible; recent amoxicillin, purulent conjunctivitis, or recurrent nonresponse favors amoxicillin-clavulanate.','Pediatric AOM; allergy and dosing need separate checks')
patch(49,'Diagnosis requires ALL 3:\n1. Acute onset (rapid onset of signs/symptoms)\n2. Middle ear effusion (MEE): bulging tympanic membrane, limited mobility, air-fluid level\n3. Middle ear inflammation: distinct erythema OR otalgia interfering with normal activity/sleep','Diagnosis: middle-ear effusion must be present, together with moderate/severe TM bulging or new otorrhea not caused by otitis externa; alternatively mild TM bulging with recent (<48 h) otalgia or intense erythema qualifies. Erythema alone is insufficient.',['aom-diagnosis'],'Correct required-vs-alternative diagnostic criteria')
patch(102,'DIAGNOSIS CRITERIA (all 3 required):\n1. Moderate-to-severe bulging of the tympanic membrane (TM) OR new onset otorrhea not due to external otitis\n2. Mild TM bulging + RECENT onset of ear pain (<48h) + intense TM erythema\n3. (OR: TM perforation with purulent discharge)','DIAGNOSIS: require middle-ear effusion plus moderate/severe TM bulging or new otorrhea not due to otitis externa; OR mild bulging with recent (<48 h) ear pain or intense erythema. These pathways are alternatives, not three simultaneous requirements.',['aom-diagnosis'],'Correct duplicate diagnostic logic')
source('hib-series','CDC','Child and Adolescent Immunization Schedule Notes','2025-07-02','https://www.cdc.gov/vaccines/hcp/imz-schedules/child-adolescent-notes.html','Hib routine vaccination','PedvaxHIB uses a two-dose primary series at ages two and four months, followed by a booster at 12–15 months; other Hib products can use a three-dose primary series.','Children; product-specific schedules')
patch(20,'Hib #3 (if Hib-OMP)','Hib primary dose #3 for products requiring it; not routine for a PedvaxHIB-only primary series',['hib-series'],'Correct reversed Hib-OMP instruction')
source('pneumococcal-adult','CDC','Adult Immunization Schedule Notes','2025-07-02','https://www.cdc.gov/vaccines/hcp/imz-schedules/adult-notes.html','Pneumococcal vaccination: Routine and Special Situations','PCV-naive/unknown-history adults ≥50: PCV15, PCV20, or PCV21. PCV15 is generally followed by PPSV23 after one year; selected high-risk groups allow eight weeks. Prior vaccine history changes the algorithm.','Adults; pregnancy and prior vaccination require separate guidance')
patch(19,'- PCV20 (Prevnar20): single dose for adults ≥65 not previously vaccinated; preferred over PCV15/PPSV23 combination\n- High-risk conditions (immunocompromised, asplenia, CKD, diabetes, smoking, COPD, heart disease) < 65: PCV20 or PCV15 followed by PPSV23','- Age ≥50 with no prior PCV13/15/20/21 or unknown history: PCV15, PCV20, or PCV21. PCV15 generally requires PPSV23 ≥1 year later (selected high-risk minimum interval 8 weeks).\n- Adults 19–49 with eligible risk conditions have a separate risk-based pathway. Prior vaccination changes the schedule; consult the current CDC algorithm.',['pneumococcal-adult'],'Update age threshold and include PCV21 without erasing other vaccines')
source('hpylori-treatment','ACG','ACG H. pylori guideline: official highlights and EBGI explanation','2024-09-17','https://gi.org/journals-publications/ebgi/schoenfeld_sep2024/','Results; corroborating 2024 guideline highlights table','Empiric optimized bismuth quadruple therapy lasts 14 days: PPI twice daily, tetracycline 500 mg four times daily, metronidazole 500 mg three/four times daily, bismuth four times daily. Clarithromycin triple therapy requires proven susceptibility.','Adult treatment; verify allergies, interactions, pregnancy, and product doses')
patch(37,'First-line triple therapy (if local clarithromycin resistance <15%):\n- Clarithromycin triple: PPI BID + clarithromycin 500mg BID + amoxicillin 1g BID × 14 days\n- Bismuth quadruple: PPI BID + bismuth subsalicylate + metronidazole + tetracycline × 10-14 days (preferred if penicillin allergy or high clarithromycin resistance)','Empiric treatment when susceptibility is unknown (ACG 2024):\n- Optimized bismuth quadruple therapy for 14 days: PPI twice daily, tetracycline 500 mg orally four times daily, metronidazole 500 mg orally three or four times daily, and bismuth four times daily (product-specific dose).\n- Clarithromycin triple therapy is not empiric first-line; use only with demonstrated susceptibility. Rifabutin triple or vonoprazan-amoxicillin dual therapy are alternatives for eligible patients.',['hpylori-treatment'],'Replace obsolete empiric clarithromycin rule while retaining diagnostic and follow-up sections')
source('stroke-2026','AHA/ASA','2026 Early Management of Acute Ischemic Stroke: Top Things to Know','2026-01-26','https://professional.heart.org/en/science-news/2026-guideline-for-the-early-management-of-patients-with-acute-ischemic-stroke/top-things-to-know','Items 3–7, 9–10','Eligible disabling stroke: alteplase or tenecteplase within 4.5 hours; selected extended-window cases require imaging criteria. EVT eligibility now includes selected large-core and basilar occlusions. Non-disabling deficits have a different antiplatelet pathway.','Acute stroke; detailed eligibility and dosing remain separate')
source('pe-2026','AHA/ACC','2026 Acute Pulmonary Embolism Guideline: Top Things to Know','2026-02-19','https://professional.heart.org/en/science-news/2026-guideline-for-the-evaluation-and-management-of-acute-pulmonary-embolism-in-adults/top-things-to-know','Items 1–10','New A–E PE categories guide disposition and advanced therapy. Eligible oral therapy favors DOACs; when parenteral therapy is required, LMWH is generally preferred. Follow symptoms/function for at least one year.','Adults; contraindications and instability need full guideline assessment')
source('sepsis-2026','SCCM','Surviving Sepsis Campaign: Adult Guidelines 2026','2026-03-23','https://sccm.org/clinical-resources/guidelines/guidelines/surviving-sepsis-campaign-international-guidelines-for-management-of-sepsis-and-septic-shock-2026','Antibiotic initiation recommendations','Shock or probable/definite sepsis: antibiotics immediately, ideally within one hour. Possible sepsis without shock: rapid investigation and antibiotics within three hours if concern persists. Low infection likelihood without shock can justify monitored deferral.','Adults; likelihood and shock status determine timing','Strong for shock/probable-definite; conditional for possible sepsis; very low certainty')
# Append scoped evidence updates to the existing long entries; never replace a whole topic.
for i,id in [(121,'stroke-2026'),(154,'pe-2026'),(116,'sepsis-2026')]:
 e=next(x for x in evidence if x['id']==id)
 changes.append(dict(index=i,old='',new='\n\nCURRENT SOURCE UPDATE — '+e['claim'],evidence=[id],reason='Add current scoped recommendation; detailed legacy assertions remain explicitly unresolved'))
source('ckd-2024','KDIGO','2024 CKD Guideline','2024-03','https://kdigo.org/wp-content/uploads/2024/03/KDIGO-2024-CKD-Guideline.pdf','Recommendation 3.4.1; 3.8.1; Practice Point 5.4.1','High-BP CKD target is standardized-office systolic <120 if tolerated, not <120/80. Finerenone is a nonsteroidal MRA. Dialysis initiation depends on symptoms, signs, quality of life, preferences, GFR and labs, not a fixed eGFR threshold.','Adults; individualize for tolerance, frailty, and comorbidities')
patch(45,'- BP target: <120/80 if tolerated (per SPRINT/evidence); ACEi or ARB for proteinuric CKD (reduces progression)','- BP: KDIGO suggests standardized-office systolic BP <120 mmHg when tolerated; this is not a routine-office <120/80 target. ACEi/ARB selection depends on albuminuria and clinical context.',['ckd-2024'],'Correct measurement-dependent systolic target')
patch(45,'- SGLT2 inhibitors: finerenone (MRA), empagliflozin/dapagliflozin — now Class 1 recommendation for DKD with albuminuria (CREDENCE, DAPA-CKD, EMPA-KIDNEY trials)','- Separate drug classes: empagliflozin/dapagliflozin are SGLT2 inhibitors; finerenone is a nonsteroidal MRA, with population-specific eligibility and potassium monitoring.',['ckd-2024'],'Correct finerenone drug-class error')
patch(45,'- GFR <15: initiate dialysis or transplant referral','- Kidney replacement planning and dialysis initiation are different decisions. Start dialysis based on symptoms, signs, quality of life, preferences, GFR and laboratory abnormalities; eGFR <15 alone is not an automatic start rule.',['ckd-2024'],'Remove isolated eGFR dialysis trigger')
source('smart-naepp','NHLBI/NAEPP','2020 Focused Updates: Clinician Guide','2020','https://www.nhlbi.nih.gov/sites/default/files/publications/Asthma%20Clinicians%20Guide%20508_02-03-21.pdf','Printed pages 3–4: Ages 4+; SMART implementation','For appropriate ages ≥4 with moderate/severe persistent asthma, ICS-formoterol maintenance-and-reliever therapy is preferred at steps 3–4. With 4.5 mcg formoterol per inhalation, daily maximum is eight puffs ages 4–11 and twelve ages ≥12. Do not use as reliever with ICS-salmeterol maintenance.','Age/product-specific NAEPP recommendations; does not certify GINA 2026 or FDA reliever labeling')
patch(48,'- Step 3: medium-dose ICS OR low-dose ICS + LABA (age ≥5) or LTRA (age <5)\n- Step 4: medium-dose ICS + LABA; consider referral to specialist','- Ages ≥4, moderate/severe persistent asthma: preferred steps 3–4 use low-/medium-dose ICS-formoterol as maintenance AND reliever (SMART), when appropriate. Age-specific pathways still apply.',['smart-naepp'],'Restore omitted federal SMART pathway')
patch(103,'Step 3 (Moderate Persistent): Low-dose ICS + LABA (if ≥5 years) OR medium-dose ICS\nStep 4: Medium-dose ICS + LABA','Steps 3–4 for appropriate ages ≥4: low-/medium-dose ICS-formoterol maintenance AND reliever (SMART). In the studied 4.5 mcg formoterol/puff preparations, maximum total daily puffs are 8 for ages 4–11 and 12 for ages ≥12; contact the clinician if more is needed. Do not combine this reliever with ICS-salmeterol maintenance.',['smart-naepp'],'Add age- and product-specific SMART limits')
source('ptsd-meds','VA/DoD','Clinician Guide to Medications for PTSD','2023','https://www.ptsd.va.gov/professional/treat/txessentials/clinician_guide_meds.asp','SSRIs; SNRIs; Combination/Adjunctive Medication','Sertraline, paroxetine and venlafaxine have strongest medication evidence; fluoxetine has insufficient evidence for or against. Recommended oral daily ranges: sertraline 50–200 mg, paroxetine 20–60 mg, venlafaxine 75–300 mg. Evidence does not establish combination superiority with psychotherapy.','Adults; ranges are not starting doses or universal titration instructions')
patch(109,'2. PHARMACOTHERAPY (strong evidence for trauma-focused therapy + medications):\n   - SSRIs (first-line): sertraline and paroxetine are FDA-APPROVED for PTSD; fluoxetine and venlafaxine also evidence-based','2. PHARMACOTHERAPY:\n   - VA/DoD supports sertraline, paroxetine and venlafaxine; fluoxetine has insufficient evidence for or against. Oral daily guideline ranges: sertraline 50–200 mg, paroxetine 20–60 mg, venlafaxine 75–300 mg. These are ranges, not universal starting doses.\n   - Evidence does not establish superior PTSD outcomes from routinely combining recommended medication with psychotherapy.',['ptsd-meds'],'Correct medication evidence and unsupported combination-superiority claim')
source('dpn-opioids','AAN','Oral and Topical Treatment of Painful Diabetic Polyneuropathy: Clinician Summary','2021','https://www.aan.com/Guidelines/home/GetGuidelineContent/1055','Page 3: Recommendations 8–9','Do not use opioids, including tramadol or tapentadol, for painful diabetic neuropathy; discuss safe tapering and nonopioid alternatives when already prescribed.','Painful diabetic neuropathy','Level B for opioids; Level C for tramadol/tapentadol')
patch(132,'- Tapentadol ER: FDA-approved for DPN pain; reserve for refractory cases','- Do not use opioids, including tramadol or tapentadol, for painful diabetic neuropathy under AAN guidance. Existing opioid treatment requires individualized safe taper discussion, not abrupt discontinuation.',['dpn-opioids'],'Separate FDA indication from guideline recommendation')
source('abfm-blueprint','ABFM','Family Medicine Exam Blueprint','2025','https://www.theabfm.org/family-medicine-exam-blueprint/','Content Area table; implementation FAQ','Official five-domain targets: Acute Care and Diagnosis 35%, Chronic Care Management 25%, Emergent and Urgent Care 20%, Preventive Care 15%, Foundations of Care 5%. Retained organ-system study weights are not these exam percentages.','ABFM exam blueprint; not disease-specific frequency predictions')
source('pregabalin-dpn','FDA label via NIH DailyMed','LYRICA prescribing information','2025-04','https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d4734e7d-5079-455e-8ff5-8f4539c998a9','Sections 2.1–2.2; renal table 2.7','Adult DPN with CrCl ≥60: start 50 mg PO three times daily; may increase to 100 mg three times daily within one week as tolerated. Maximum 300 mg/day for this indication; renal impairment requires lower dosing.','Adult diabetic neuropathic pain; not other indications')
patch(132,'- Pregabalin (Lyrica) 150-600 mg/day: FDA-approved; titrate; sedation, weight gain, edema','- Pregabalin for adult diabetic neuropathic pain, CrCl ≥60 mL/min: 50 mg orally three times daily initially; may increase within 1 week to 100 mg three times daily based on response/tolerability. Maximum 300 mg/day for this indication; reduce for renal impairment using the label table. Monitor sedation, edema and weight.',['pregabalin-dpn'],'Separate indication-specific maximum from other pregabalin indications')
source('duloxetine-dpn','FDA label via NIH DailyMed','Duloxetine delayed-release prescribing information',None,'https://www.dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=fc9ad025-88c8-4c3d-8cd0-3ad60a7a47e8&type=display','Sections 2.3 and 2.6','DPN dose is 60 mg PO daily; higher doses lack additional significant benefit and are less tolerated. Avoid chronic liver disease/cirrhosis or GFR <30.','Adult diabetic neuropathic pain; chosen label version, current product reconciliation pending')
patch(132,'- Duloxetine (Cymbalta) 60-120 mg/day: FDA-approved; NNT ~5; SNRI; also treats comorbid depression','- Duloxetine for diabetic neuropathic pain: 60 mg orally once daily; consider a lower starting dose for tolerability. Doses above 60 mg/day lack additional significant benefit and are less tolerated. Avoid chronic liver disease/cirrhosis or GFR <30 mL/min.',['duloxetine-dpn'],'Correct indication-specific dosing and remove unsupported NNT')
source('naltrexone-transition','FDA label via NIH DailyMed','VIVITROL prescribing information','2026-05','https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=cd11c435-b0f0-4bb9-ae78-60f101f3703f','Sections 2.1 and 5.3','Before VIVITROL, minimum opioid-free interval is 7–10 days after short-acting opioids; withdrawal vulnerability may persist up to two weeks after buprenorphine or methadone.','Extended-release naltrexone initiation; individualized supervised assessment is required')
patch(110,'- Requires opioid-free for 7-10 days before initiation (5-7 days for buprenorphine, 7-10 days for methadone) to avoid precipitated withdrawal','- Before extended-release naltrexone, patients previously using short-acting opioids need at least 7–10 opioid-free days. Those transitioning from buprenorphine or methadone may remain vulnerable to precipitated withdrawal for up to 2 weeks; do not apply the old shortened intervals.',['naltrexone-transition'],'Correct potentially dangerous agonist-to-antagonist transition intervals')
source('lisdexamfetamine-class','FDA','VYVANSE prescribing information','2026','https://www.accessdata.fda.gov/drugsatfda_docs/label/2026/021977s052lbl.pdf','Section 12.1','Lisdexamfetamine is a prodrug of dextroamphetamine; it is not a methylphenidate formulation.','Medication identity; full ADHD treatment review remains pending')
patch(100,'1. Methylphenidate (Ritalin, Concerta, Vyvanse-type): most studied; standard and extended-release','1. Methylphenidate formulations include Ritalin and Concerta. Vyvanse is lisdexamfetamine, a prodrug of dextroamphetamine, not methylphenidate.',['lisdexamfetamine-class'],'Correct drug class without changing ADHD features')
source('gbs-screening','CDC','Screening for Group B Strep Bacteria',None,'https://www.cdc.gov/group-b-strep/testing/index.html','When to get screened','GBS screening is performed during the 36th or 37th week of each pregnancy; intrapartum prophylaxis requires its own obstetric algorithm.','Pregnancy; screening timing, not full labor management')
patch(33,'Group B Streptococcus (GBS): culture at 35-37 weeks; prophylactic penicillin G in labor if positive (or prior GBS infant, GBS bacteriuria, or unknown status + ≥37 weeks + ≥18h ROM + fever)','Group B Streptococcus: screen during the 36th or 37th week of each pregnancy. Determine intrapartum prophylaxis from the current obstetric algorithm; the old combined unknown-status condition is not a valid decision rule.',['gbs-screening'],'Correct timing and remove malformed prophylaxis rule')
source('prep-populations','CDC','Clinical Guidance for PrEP','2026-04-30','https://www.cdc.gov/hivnexus/hcp/prep/index.html','Treatment options; Evaluation','F/TAF PrEP excludes receptive vaginal exposure; it is not defined by a blanket MSM/non-MSM label. F/TDF covers sexual and injection risk; HIV status and method-specific baseline assessments must be checked.','PrEP candidates; do not interpret source list as exhaustive current product inventory')
patch(31,'tenofovir AF (Descovy, for non-receptive sex only)','tenofovir AF (Descovy/F-TAF; not for HIV prevention through receptive vaginal sex)',['prep-populations'],'Correct exposure-specific restriction')
patch(111,'- TAF/FTC (Descovy): alternative; approved for non-MSM after pregnancy concerns excluded','- F/TAF (Descovy): option for sexual HIV prevention excluding receptive vaginal exposure. Eligibility is exposure-specific, not a blanket non-MSM rule.',['prep-populations'],'Correct false PrEP eligibility statement')
# Replace obsolete acute-care recommendations at their original location.
patch(121,'- Extended window (3.0-4.5h): avoid if age >80, on anticoagulant, NIHSS >25, hx both DM + prior stroke, imaging >1/3 MCA territory','- Apply current patient-specific eligibility, not the old categorical 3–4.5-hour exclusions. The 2026 guideline endorses alteplase or tenecteplase for eligible disabling deficits within 4.5 hours, and imaging-selected extended-window treatment in selected patients.',['stroke-2026'],'Remove obsolete categorical extended-window exclusions')
patch(121,'- Indication: LVO (ICA, MCA M1/M2), NIHSS ≥6, ASPECTS ≥6, onset <6 hours (selected patients up to 24h with perfusion imaging)','- Use the 2026 imaging- and vessel-specific EVT pathway, including selected large-core strokes and basilar occlusion; the older narrow rule is not a complete eligibility screen.',['stroke-2026'],'Avoid excluding newer eligible EVT populations')
patch(116,'3. Broad-spectrum antibiotics within 1 hour (goal immediately upon recognition)','3. Match timing to certainty and shock: septic shock or probable/definite sepsis warrants immediate antibiotics, ideally within 1 hour. Possible sepsis without shock warrants rapid investigation and antibiotics within 3 hours if infection concern persists.',['sepsis-2026'],'Replace universal timing with current likelihood-specific recommendations')
source('toxo-prophylaxis','NIH','Toxoplasma gondii Encephalitis: Adult and Adolescent OIs',None,'https://clinicalinfo.hiv.gov/en/guidelines/hiv-clinical-guidelines-adult-and-adolescent-opportunistic-infections/toxoplasmosis','Preventing Disease: Primary Prophylaxis','Primary toxoplasma prophylaxis is indicated for Toxoplasma IgG-positive people with CD4 <100; TMP-SMX one DS tablet PO daily is preferred and also covers PCP.','Adults/adolescents with HIV','AII')
patch(111,'  • CD4 <200: TMP-SMX for PCP and toxoplasma prophylaxis','  • Assess PCP eligibility separately. Toxoplasma primary prophylaxis requires positive Toxoplasma IgG and CD4 <100 cells/mcL; preferred TMP-SMX one DS tablet orally daily also covers PCP.',['toxo-prophylaxis'],'Correct false universal toxoplasma threshold')
patch(111,'  • CD4 <50: azithromycin for MAC prophylaxis; fluconazole for candida/cryptococcus (resource-limited settings)','  • MAC primary prophylaxis: CD4 <50 cells/mcL plus absent/non-suppressive ART; not needed when effective ART is started immediately. Do not infer other OI prophylaxis solely from this threshold.',['mac-prophylaxis'],'Qualify duplicate MAC statement and remove unsupported blanket antifungal prophylaxis')
source('art-timing','NIH','Initiation of Antiretroviral Therapy',None,'https://clinicalinfo.hiv.gov/en/guidelines/hiv-clinical-guidelines-adult-and-adolescent-arv/initiation-antiretroviral-therapy','ART in Acute OIs and During Hospitalization','Start ART promptly for most people, but cryptococcal meningitis and TB meningitis may require delayed initiation because of serious IRIS risk; use the specific OI guideline.','People with HIV; not a universal same-day rule for every OI')
patch(111,'- ALL people with HIV, regardless of CD4 count — START IMMEDIATELY (same-day ART recommended)\n- High urgency (start ASAP, even same day): AIDS-defining illness, pregnancy, acute HIV infection, to prevent transmission','- ART is recommended for all people with HIV and should generally start promptly.\n- Opportunistic-infection-specific timing matters: cryptococcal meningitis and TB meningitis may require delay to reduce serious IRIS risk. Do not apply same-day initiation to every AIDS-defining illness.',['art-timing'],'Remove unsafe universal immediate-ART instruction')
source('lung-screen-stop','USPSTF','Lung Cancer Screening','2021-03-09','https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/lung-cancer-screening','Recommendation Summary','Annual LDCT for eligible ages 50–80 with ≥20 pack-years and current smoking or quitting within 15 years; stop once 15 years without smoking or if health precludes curative surgery.','USPSTF eligibility; other organizations may differ','Grade B')
patch(23,'- Person has not smoked in >15 years','- Person has not smoked for 15 years (USPSTF stopping rule)',['lung-screen-stop'],'Correct boundary condition')
source('dka-consensus','ADA/EASD/JBDS/AACE/DTS','Hyperglycaemic crises in adults with diabetes: a consensus report','2024-06-22','https://link.springer.com/article/10.1007/s00125-024-06183-8','Section 3 and Figure 2a','Adult DKA requires diabetes/history or glucose ≥200 mg/dL, ketosis (beta-hydroxybutyrate ≥3 mmol/L or urine ≥2+), and acidosis (pH <7.3 and/or bicarbonate <18 mmol/L). Euglycemic DKA can occur.','Adult hyperglycemic crises; not a full pediatric protocol')
patch(10,'DKA: pH <7.3, glucose >250, ketones; fluids + insulin drip + potassium replacement','Adult DKA requires all three: diabetes history or glucose ≥200 mg/dL; beta-hydroxybutyrate ≥3 mmol/L or urine ketones ≥2+; and pH <7.3 and/or bicarbonate <18 mmol/L. Normal-range glucose does not exclude DKA in someone with diabetes. Treatment requires fluids, insulin, electrolyte management and precipitant treatment under an appropriate protocol.',['dka-consensus'],'Correct diagnostic glucose threshold and recognize euglycemic DKA')
